import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.ClgMjOt7.js";const u=JSON.parse('{"title":"外観 & 個人設定・バックアップ","description":"テーマ設定、プロキシ、ミュート管理、JSON バックアップ","frontmatter":{"title":"外観 & 個人設定・バックアップ","description":"テーマ設定、プロキシ、ミュート管理、JSON バックアップ"},"headers":[],"relativePath":"features/personalization.md","filePath":"features/personalization.md","lastUpdated":1786166106000}'),c={name:"features/personalization.md"};function i(r,e,n,s,l,p){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="外観-個人設定・バックアップ" tabindex="-1">外観 &amp; 個人設定・バックアップ <a class="header-anchor" href="#外観-個人設定・バックアップ" aria-label="Permalink to &quot;外観 &amp; 個人設定・バックアップ&quot;">​</a></h1><p><code>AppSettings</code> データストアに保持される各種カスタマイズ機能の仕様です。</p><hr><h2 id="外観-テーマ設定-generalsettingsscreen" tabindex="-1">外観 &amp; テーマ設定 (<code>GeneralSettingsScreen</code>) <a class="header-anchor" href="#外観-テーマ設定-generalsettingsscreen" aria-label="Permalink to &quot;外観 &amp; テーマ設定 (`GeneralSettingsScreen`)&quot;">​</a></h2><ul><li><code>themeMode</code>: テーマの選択 (<code>system</code> / <code>light</code> / <code>dark</code>)</li><li><code>amoledMode</code>: 背景色に純黒 (<code>#000000</code>) を使用する AMOLED モード (Boolean)</li><li><code>useDynamicColor</code>: Android 12+ Material You ダイナミックカラーの適用 (Boolean)</li><li><code>seedColor</code>: ダイナミックカラー無効時のカスタムシードカラー値 (<code>0xFF42A5F5L</code> 等)</li><li><code>appLanguage</code>: アプリ表示言語 (<code>system</code> / <code>ja</code> / <code>en</code>)</li><li><code>appFont</code>: フォント設定 (<code>system</code> / カスタムフォント)</li></ul><hr><h2 id="ネットワーク-プロキシ設定-imagesettingsscreen" tabindex="-1">ネットワーク &amp; プロキシ設定 (<code>ImageSettingsScreen</code>) <a class="header-anchor" href="#ネットワーク-プロキシ設定-imagesettingsscreen" aria-label="Permalink to &quot;ネットワーク &amp; プロキシ設定 (`ImageSettingsScreen`)&quot;">​</a></h2><ul><li><code>pixivNetworkMode</code>: ネットワーク接続モード (<code>standard</code> / <code>proxy</code>)</li><li><code>pixivImageProxyBaseUrl</code>: ドメインブロック等を回避するためのカスタムプロキシサーバー URL</li></ul><hr><h2 id="ミュート機能-mutesettingsscreen" tabindex="-1">ミュート機能 (<code>MuteSettingsScreen</code>) <a class="header-anchor" href="#ミュート機能-mutesettingsscreen" aria-label="Permalink to &quot;ミュート機能 (`MuteSettingsScreen`)&quot;">​</a></h2><p>フィードや検索結果から特定のコンテンツを除外できます。</p><ul><li><code>mutedUsers</code>: 除外するユーザー ID のリスト (<code>List&lt;Long&gt;</code>)</li><li><code>mutedTags</code>: 除外するタグ文字列のリスト (<code>List&lt;String&gt;</code>)</li><li><code>mutedIllusts</code>: 除外する作品 ID のリスト (<code>List&lt;Long&gt;</code>)</li></ul><hr><h2 id="データバックアップ-復元-appdatascreen" tabindex="-1">データバックアップ &amp; 復元 (<code>AppDataScreen</code>) <a class="header-anchor" href="#データバックアップ-復元-appdatascreen" aria-label="Permalink to &quot;データバックアップ &amp; 復元 (`AppDataScreen`)&quot;">​</a></h2><p>設定項目、ウォッチリスト、ミュートリストなどを JSON フォーマットでエクスポート / インポートできます。</p><ul><li><strong>エクスポート</strong>: 設定データをローカルストレージへ <code>.json</code> ファイルとして書き出し。</li><li><strong>インポート</strong>: 外部の <code>.json</code> ファイルを読み込み、DataStore および Room データベースに値を反映。</li></ul>',16)])])}const g=o(c,[["render",i]]);export{u as __pageData,g as default};
